import org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;
import org.springframework.security.oauth2.jwt.JwtClaimValidator;
import org.springframework.security.oauth2.jwt.JwtValidators;
import org.springframework.security.oauth2.jwt.NimbusReactiveJwtDecoder;
import org.springframework.security.oauth2.jwt.ReactiveJwtDecoder;
import org.springframework.security.web.server.SecurityWebFilterChain;

@Configuration
@EnableWebFluxSecurity
public class SecurityConfig {

    /** Which routes are open, which need a valid token, which need the admin scope. */
    @Bean
    SecurityWebFilterChain security(ServerHttpSecurity http) {
        return http
                .csrf(ServerHttpSecurity.CsrfSpec::disable)        // stateless API, no cookies
                .authorizeExchange(ex -&gt; ex
                        // open: getting a token, and the public keys to check one
                        .pathMatchers("/auth/register", "/auth/login", "/auth/.well-known/**").permitAll()
                        // open: browsing the catalog
                        .pathMatchers(HttpMethod.GET, "/catalog/**").permitAll()
                        // admin only: changing the catalog (scope claim "user admin")
                        .pathMatchers("/catalog/**").hasAuthority("SCOPE_admin")
                        // health, metrics, routes: the edge never forwards /actuator from outside
                        .pathMatchers("/actuator/**").permitAll()
                        // everything else (and every future route): any valid token
                        .anyExchange().authenticated())
                .oauth2ResourceServer(oauth -&gt; oauth.jwt(Customizer.withDefaults()))
                .build();
    }

    /** Signature from the JWKS of auth, plus expiry, issuer and audience checks. */
    @Bean
    ReactiveJwtDecoder jwtDecoder(@Value("${spring.security.oauth2.resourceserver.jwt.jwk-set-uri}") String jwksUri,
                                  @Value("${jwt.issuer}") String issuer,
                                  @Value("${jwt.audience}") String audience) {
        var decoder = NimbusReactiveJwtDecoder.withJwkSetUri(jwksUri).build();
        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator&lt;&gt;(
                JwtValidators.createDefaultWithIssuer(issuer),     // exp, nbf, iss
                new JwtClaimValidator&lt;List&lt;String&gt;&gt;("aud", aud -&gt; aud != null &amp;&amp; aud.contains(audience))));
        return decoder;
    }
}
</code></pre> <ul> <li>Rules are evaluated in order; the first match wins. <code>anyExchange().authenticated()</code> is the safe default: a new route added next month is protected unless someone opens it explicitly.</li> <li><code>oauth2ResourceServer().jwt()</code> turns the gateway into an OAuth 2.0 resource server: it reads <code>Authorization: Bearer …</code>, validates the token with the decoder below and maps the <code>scope</code> claim to authorities (<code>SCOPE_user</code>, <code>SCOPE_admin</code>).</li> <li>The decoder downloads the JWKS from <code>auth</code> once and caches it; it refetches only when a token arrives with an unknown <code>kid</code>. That is why validation is local and cheap.</li> <li>A missing or invalid token gets <code>401 Unauthorized</code> (with a <code>WWW-Authenticate</code> header); a valid token without the needed scope gets <code>403 Forbidden</code>.</li> </ul>

services/gateway/src/main/java/boxoffice/gateway/UserHeadersFilter.java<pre><code>package boxoffice.gateway;

import org.springframework.cloud.gateway.filter.GatewayFilterChain;
import org.springframework.cloud.gateway.filter.GlobalFilter;
import org.springframework.core.Ordered;
import org.springframework.security.core.context.ReactiveSecurityContextHolder;
import org.springframework.security.core.context.SecurityContext;
import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ServerWebExchange;
import reactor.core.publisher.Mono;

/**
 * Tells the services who the user is: X-User-Id, X-User-Email, X-User-Scope.
 * Headers with these names coming from the client are always removed first,
 * otherwise anyone could claim to be anyone.
 */
@Component
public class UserHeadersFilter implements GlobalFilter, Ordered {

    @Override
    public Mono&lt;Void&gt; filter(ServerWebExchange exchange, GatewayFilterChain chain) {
        var cleaned = exchange.mutate()
                .request(r -&gt; r.headers(h -&gt; {
                    h.remove("X-User-Id");
                    h.remove("X-User-Email");
                    h.remove("X-User-Scope");
                }))
                .build();
        return ReactiveSecurityContextHolder.getContext()
                .map(SecurityContext::getAuthentication)
                .filter(JwtAuthenticationToken.class::isInstance)
                .cast(JwtAuthenticationToken.class)
                .map(auth -&gt; cleaned.mutate()
                        .request(r -&gt; r.headers(h -&gt; {
                            var jwt = auth.getToken();
                            h.set("X-User-Id", jwt.getSubject());
                            h.set("X-User-Email", jwt.getClaimAsString("email"));
                            h.set("X-User-Scope", jwt.getClaimAsString("scope"));
                        }))
                        .build())
                .defaultIfEmpty(cleaned)          // anonymous request on an open route
                .flatMap(chain::filter);
    }

    @Override
    public int getOrder() {
        return Ordered.HIGHEST_PRECEDENCE;
    }
}
</code></pre> <p>A <code>GlobalFilter</code> runs for every route. It first strips any <code>X-User-*</code> header sent by the client, then, if the request carries a validated JWT, adds the identity taken from the token. Services read a plain header instead of parsing tokens — simple, but it only holds as long as nobody can reach the services without crossing the gateway.</p>

services/catalog/src/main/java/boxoffice/catalog/EventCache.java<pre><code>package boxoffice.catalog;

import io.micrometer.core.instrument.MeterRegistry;
import java.time.Duration;
import java.util.UUID;
import java.util.concurrent.ThreadLocalRandom;
import java.util.function.Supplier;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.dao.DataAccessException;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;
import tools.jackson.databind.json.JsonMapper;

/**
 * Cache-aside in Redis. The application asks the cache first; on a miss it loads from
 * the database and writes the JSON into the cache with a TTL. Values are stored as the
 * exact JSON returned to clients, so a hit costs no database access and no serialization.
 */
@Component
public class EventCache {

    private static final Logger log = LoggerFactory.getLogger(EventCache.class);

    /** The JSON body and what happened: HIT, MISS or BYPASS (cache disabled). */
    public record Result(String json, String outcome) { }

    private final StringRedisTemplate redis;
    private final JsonMapper mapper;            // Jackson 3 (Spring Boot 4)
    private final MeterRegistry metrics;
    private final boolean enabled;
    private final boolean stampedeProtection;
    private final Duration eventTtl;
    private final Duration listTtl;

    public EventCache(StringRedisTemplate redis, JsonMapper mapper, MeterRegistry metrics,
                      @Value("${catalog.cache.enabled}") boolean enabled,
                      @Value("${catalog.cache.stampede-protection}") boolean stampedeProtection,
                      @Value("${catalog.cache.event-ttl}") Duration eventTtl,
                      @Value("${catalog.cache.list-ttl}") Duration listTtl) {
        this.redis = redis;
        this.mapper = mapper;
        this.metrics = metrics;
        this.enabled = enabled;
        this.stampedeProtection = stampedeProtection;
        this.eventTtl = eventTtl;
        this.listTtl = listTtl;
    }

    public Duration eventTtl() { return eventTtl; }
    public Duration listTtl() { return listTtl; }

    public Result get(String key, Duration ttl, Supplier&lt;?&gt; loader) {
        if (!enabled) {
            return count(new Result(toJson(loader.get()), "BYPASS"));
        }
        var cached = read(key);
        if (cached != null) {
            return count(new Result(cached, "HIT"));
        }
        if (stampedeProtection) {
            var lockKey = key + ":lock";
            var token = UUID.randomUUID().toString();
            if (tryLock(lockKey, token)) {
                try {
                    cached = read(key);               // someone may have filled it meanwhile
                    if (cached != null) {
                        return count(new Result(cached, "HIT"));
                    }
                    return count(load(key, ttl, loader));
                } finally {
                    unlock(lockKey, token);
                }
            }
            // another request is already loading this key: wait for it instead of
            // sending one more identical query to the database
            for (int i = 0; i &lt; 20; i++) {
                sleep(Duration.ofMillis(25));
                cached = read(key);
                if (cached != null) {
                    return count(new Result(cached, "HIT"));
                }
            }
        }
        return count(load(key, ttl, loader));
    }

    public void evict(String key) {
        try {
            redis.delete(key);
        } catch (DataAccessException e) {
            log.warn("cache evict failed for {}: {}", key, e.getMessage());
        }
    }

    // ---- internals --------------------------------------------------------

    private Result load(String key, Duration ttl, Supplier&lt;?&gt; loader) {
        var json = toJson(loader.get());
        try {
            redis.opsForValue().set(key, json, withJitter(ttl));
        } catch (DataAccessException e) {
            log.warn("cache write failed for {}: {}", key, e.getMessage());
        }
        return new Result(json, "MISS");
    }

    private String read(String key) {
        try {
            return redis.opsForValue().get(key);
        } catch (DataAccessException e) {
            // Redis down or slow: the cache is an optimization, not a dependency
            log.warn("cache read failed for {}: {}", key, e.getMessage());
            return null;
        }
    }

    private boolean tryLock(String lockKey, String token) {
        try {
            // SET lockKey token NX PX 2000: only one request in the whole cluster gets it
            return Boolean.TRUE.equals(redis.opsForValue().setIfAbsent(lockKey, token, Duration.ofSeconds(2)));
        } catch (DataAccessException e) {
            return true;                              // no Redis, no lock: just load
        }
    }

    private void unlock(String lockKey, String token) {
        try {
            // delete only our own lock (it may have expired and been taken by someone else);
            // get + delete is not atomic: production code uses a Lua script for this
            if (token.equals(redis.opsForValue().get(lockKey))) {
                redis.delete(lockKey);
            }
        } catch (DataAccessException e) {
            log.debug("unlock failed: {}", e.getMessage());
        }
    }

    /** TTL plus up to 10% random extra, so that keys written together do not expire together. */
    private static Duration withJitter(Duration ttl) {
        long extra = (long) (ttl.toMillis() * 0.10 * ThreadLocalRandom.current().nextDouble());
        return ttl.plusMillis(extra);
    }

    private Result count(Result result) {
        metrics.counter("catalog.cache.requests", "result", result.outcome()).increment();
        return result;
    }

    private String toJson(Object value) {
        return mapper.writeValueAsString(value);    // Jackson 3 exceptions are unchecked
    }

    private static void sleep(Duration d) {
        try {
            Thread.sleep(d);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
</code></pre> <p>Design decisions, one by one:</p> <ul> <li>Store the response JSON, not Java objects. A hit returns the string as-is: no database, no object mapping, no serialization. It is also readable with <code>redis-cli GET</code>.</li> <li>Jackson 3: Spring Boot 4 ships Jackson 3 (package <code>tools.jackson</code>). The JSON bean is a <code>JsonMapper</code>, and its exceptions are unchecked, so <code>toJson</code> needs no <code>try/catch</code>.</li> <li>TTL with jitter (<code>+0–10%</code>): keys written in the same second do not all expire in the same second.</li> <li>Redis failures become misses (<code>catch (DataAccessException e)</code>): the cache is an optimization, never a hard dependency. With Redis down, <code>catalog</code> is as slow as before lab 5, but it works.</li> <li>A counter per outcome (<code>catalog.cache.requests{result=HIT|MISS|BYPASS}</code>) on every replica, visible at <code>/actuator/metrics/catalog.cache.requests</code> — and on Grafana in lab 8.</li> <li>The stampede protection branch is explained in step 2; it is off by default so that you can see the problem first.</li> </ul>

services/inventory/src/main/java/boxoffice/inventory/HoldService.java<pre><code>package boxoffice.inventory;

import java.time.Duration;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.List;
import java.util.UUID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * Holds: "these seats are mine for 10 minutes". The one rule that must never break:
 * a seat belongs to at most ONE live hold. Three ways to (try to) enforce it are
 * selectable with INVENTORY_LOCKING, so you can measure each one.
 */
@Service
public class HoldService {

    private static final Logger log = LoggerFactory.getLogger(HoldService.class);

    private record Seat(long id, String status, int version) { }

    private final JdbcClient jdbc;
    private final String locking;
    private final Duration holdTtl;
    private final int maxSeats;

    public HoldService(JdbcClient jdbc,
                       @Value("${inventory.locking}") String locking,
                       @Value("${inventory.hold-ttl}") Duration holdTtl,
                       @Value("${inventory.max-seats-per-hold}") int maxSeats) {
        this.jdbc = jdbc;
        this.locking = locking;
        this.holdTtl = holdTtl;
        this.maxSeats = maxSeats;
        log.info("seat locking strategy: {}", locking);
    }

    @Transactional        // READ COMMITTED (PostgreSQL's default), on the primary
    public HoldOut hold(String userId, HoldIn in) {
        var seatIds = in.seatIds().stream().distinct().sorted().toList();
        if (seatIds.size() &gt; maxSeats) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "at most " + maxSeats + " seats per hold");
        }
        var holdId = UUID.randomUUID();
        var expiresAt = OffsetDateTime.now(ZoneOffset.UTC).plus(holdTtl);

        switch (locking) {
            case "naive" -&gt; holdNaive(in.eventId(), seatIds, holdId);
            case "optimistic" -&gt; holdOptimistic(in.eventId(), seatIds, holdId);
            default -&gt; holdPessimistic(in.eventId(), seatIds, holdId);
        }

        jdbc.sql("""
                INSERT INTO inventory.holds (id, event_id, user_id, status, expires_at)
                VALUES (:id, :eventId, :userId, 'ACTIVE', :expiresAt)""")
                .param("id", holdId).param("eventId", in.eventId())
                .param("userId", userId).param("expiresAt", expiresAt)
                .update();
        for (var seatId : seatIds) {
            jdbc.sql("INSERT INTO inventory.hold_seats (hold_id, seat_id) VALUES (:holdId, :seatId)")
                    .param("holdId", holdId).param("seatId", seatId)
                    .update();
        }
        return new HoldOut(holdId, in.eventId(), "ACTIVE", expiresAt, seatIds);
    }

    // ---- strategy 1: check-then-act, no lock (WRONG on purpose) ---------------
    private void holdNaive(long eventId, List&lt;Long&gt; seatIds, UUID holdId) {
        var seats = read(eventId, seatIds, "");
        requireAvailable(seats, seatIds);
        // race window: another transaction may have read the same AVAILABLE seats and
        // be about to run this same UPDATE — both will "win"
        jdbc.sql("UPDATE inventory.seats SET status = 'HELD', hold_id = :holdId WHERE id IN (:ids)")
                .param("holdId", holdId).param("ids", seatIds)
                .update();
    }

    // ---- strategy 2: pessimistic, SELECT ... FOR UPDATE -----------------------
    private void holdPessimistic(long eventId, List&lt;Long&gt; seatIds, UUID holdId) {
        // row locks until commit; a second transaction on the same seats WAITS here.
        // Locking in id order (ORDER BY id) prevents deadlocks between overlapping holds.
        var seats = read(eventId, seatIds, "ORDER BY id FOR UPDATE");
        requireAvailable(seats, seatIds);
        jdbc.sql("UPDATE inventory.seats SET status = 'HELD', hold_id = :holdId, version = version + 1 WHERE id IN (:ids)")
                .param("holdId", holdId).param("ids", seatIds)
                .update();
    }

    // ---- strategy 3: optimistic, compare-and-set on a version column ---------------
    private void holdOptimistic(long eventId, List&lt;Long&gt; seatIds, UUID holdId) {
        var seats = read(eventId, seatIds, "");                      // no lock
        requireAvailable(seats, seatIds);
        for (var seat : seats) {
            int changed = jdbc.sql("""
                    UPDATE inventory.seats
                    SET status = 'HELD', hold_id = :holdId, version = version + 1
                    WHERE id = :id AND version = :version AND status = 'AVAILABLE'""")
                    .param("holdId", holdId).param("id", seat.id()).param("version", seat.version())
                    .update();
            if (changed == 0) {
                // someone changed this seat after we read it: give up (the exception rolls back)
                throw new ResponseStatusException(HttpStatus.CONFLICT, "seat " + seat.id() + " was just taken");
            }
        }
    }

    private List&lt;Seat&gt; read(long eventId, List&lt;Long&gt; seatIds, String suffix) {
        return jdbc.sql("SELECT id, status, version FROM inventory.seats "
                        + "WHERE event_id = :eventId AND id IN (:ids) " + suffix)
                .param("eventId", eventId).param("ids", seatIds)
                .query((rs, n) -&gt; new Seat(rs.getLong("id"), rs.getString("status"), rs.getInt("version")))
                .list();
    }

    private static void requireAvailable(List&lt;Seat&gt; seats, List&lt;Long&gt; seatIds) {
        if (seats.size() != seatIds.size()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "some seats do not belong to this event");
        }
        if (seats.stream().anyMatch(s -&gt; !"AVAILABLE".equals(s.status()))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "some seats are not available");
        }
    }

    // ---- reading, confirming and releasing a hold (always on the primary) -----

    @Transactional        // NOT readOnly: read-your-writes, the user just created it
    public HoldOut find(String userId, UUID holdId) {
        var hold = jdbc.sql("""
                SELECT id, event_id, status, expires_at FROM inventory.holds
                WHERE id = :id AND user_id = :userId""")
                .param("id", holdId).param("userId", userId)
                .query((rs, n) -&gt; new HoldOut(rs.getObject("id", UUID.class), rs.getLong("event_id"),
                        rs.getString("status"), rs.getObject("expires_at", OffsetDateTime.class), List.of()))
                .optional()
                .orElseThrow(() -&gt; new ResponseStatusException(HttpStatus.NOT_FOUND, "hold not found"));
        var seatIds = jdbc.sql("SELECT seat_id FROM inventory.hold_seats WHERE hold_id = :id ORDER BY seat_id")
                .param("id", holdId).query(Long.class).list();
        return new HoldOut(hold.id(), hold.eventId(), hold.status(), hold.expiresAt(), seatIds);
    }

    /** Payment succeeded (lab 7 calls this): seats become SOLD. */
    @Transactional
    public HoldOut confirm(String userId, UUID holdId) {
        int changed = jdbc.sql("""
                UPDATE inventory.holds SET status = 'CONFIRMED'
                WHERE id = :id AND user_id = :userId AND status = 'ACTIVE' AND expires_at &gt; now()""")
                .param("id", holdId).param("userId", userId)
                .update();
        if (changed == 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "hold is not active (expired, released or unknown)");
        }
        jdbc.sql("UPDATE inventory.seats SET status = 'SOLD', version = version + 1 WHERE hold_id = :id")
                .param("id", holdId).update();
        return find(userId, holdId);
    }

    @Transactional
    public void release(String userId, UUID holdId) {
        int changed = jdbc.sql("""
                UPDATE inventory.holds SET status = 'RELEASED'
                WHERE id = :id AND user_id = :userId AND status = 'ACTIVE'""")
                .param("id", holdId).param("userId", userId)
                .update();
        if (changed == 0) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "no active hold " + holdId);
        }
        freeSeatsOf(holdId);
    }

    private void freeSeatsOf(UUID holdId) {
        jdbc.sql("""
                UPDATE inventory.seats SET status = 'AVAILABLE', hold_id = NULL, version = version + 1
                WHERE hold_id = :id AND status = 'HELD'""")
                .param("id", holdId).update();
    }

    /**
     * Every 5 s, expire old holds and free their seats. FOR UPDATE SKIP LOCKED lets several
     * inventory replicas run this job at the same time without processing the same hold twice.
     */
    @Scheduled(fixedDelay = 5000)
    @Transactional
    public void expireHolds() {
        int freed = jdbc.sql("""
                WITH expired AS (
                    UPDATE inventory.holds SET status = 'EXPIRED'
                    WHERE id IN (SELECT id FROM inventory.holds
                                 WHERE status = 'ACTIVE' AND expires_at &lt; now()
                                 ORDER BY expires_at
                                 LIMIT 500
                                 FOR UPDATE SKIP LOCKED)
                    RETURNING id)
                UPDATE inventory.seats
                SET status = 'AVAILABLE', hold_id = NULL, version = version + 1
                WHERE status = 'HELD' AND hold_id IN (SELECT id FROM expired)""")
                .update();
        if (freed &gt; 0) {
            log.info("expired holds freed {} seats", freed);
        }
    }
}
</code></pre> <p>Read it strategy by strategy:</p> <ul> <li>naive: <code>read(…, "")</code> then an unconditional <code>UPDATE</code>. The comment marks the race window.</li> <li>pessimistic: <code>read(…, "ORDER BY id FOR UPDATE")</code>. The second transaction blocks on the row locks; when the first commits, PostgreSQL re-reads the locked rows, the second sees <code>HELD</code>, and <code>requireAvailable</code> throws <code>409</code>. Locking in a fixed order (<code>ORDER BY id</code>) matters: fan A holding seats 7→8 and fan B holding 8→7 in opposite order would deadlock.</li> <li>optimistic: no locks; the <code>UPDATE</code> only succeeds if <code>version</code> is still the one we read. If another transaction changed the seat in between, 0 rows change, we throw, and <code>@Transactional</code> rolls back everything (including seats already updated in the loop).</li> <li>Every hold also checks that all seats belong to the event (<code>400</code> otherwise) and limits a hold to 6 seats.</li> <li><code>find</code>, <code>confirm</code> and <code>release</code> filter by <code>user_id</code>: a fan cannot see or cancel somebody else's hold (that would be an IDOR, insecure direct object reference — OWASP API #1).</li> <li><code>expireHolds</code> runs every 5 s on every replica; <code>FOR UPDATE SKIP LOCKED</code> lets several replicas share the work without blocking each other or processing a hold twice — the same trick used by job queues built on PostgreSQL.</li> </ul> <p>The read-only queries live in a separate class, because they go to the replica (step 2):</p> services/inventory/src/main/java/boxoffice/inventory/SeatQueries.java<pre><code>package boxoffice.inventory;

import java.util.List;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Read-only queries: they run on the REPLICA (readOnly = true), so they may be slightly stale. */
@Service
public class SeatQueries {

    private final JdbcClient jdbc;

    public SeatQueries(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    @Transactional(readOnly = true)
    public List&lt;SectionAvailability&gt; availability(long eventId) {
        return jdbc.sql("""
                SELECT section,
                       count(*) FILTER (WHERE status = 'AVAILABLE') AS available,
                       count(*) FILTER (WHERE status = 'HELD')      AS held,
                       count(*) FILTER (WHERE status = 'SOLD')      AS sold
                FROM inventory.seats
                WHERE event_id = :eventId
                GROUP BY section
                ORDER BY section""")
                .param("eventId", eventId)
                .query((rs, n) -&gt; new SectionAvailability(rs.getString("section"),
                        rs.getLong("available"), rs.getLong("held"), rs.getLong("sold")))
                .list();
    }

    @Transactional(readOnly = true)
    public List&lt;SeatOut&gt; seats(long eventId, String section) {
        return jdbc.sql("""
                SELECT id, section, seat_row, seat_number, price, status
                FROM inventory.seats
                WHERE event_id = :eventId AND section = :section
                ORDER BY seat_row, seat_number""")
                .param("eventId", eventId)
                .param("section", section)
                .query((rs, n) -&gt; new SeatOut(rs.getLong("id"), rs.getString("section"),
                        rs.getInt("seat_row"), rs.getInt("seat_number"),
                        rs.getBigDecimal("price"), rs.getString("status")))
                .list();
    }

    /** Seats that belong to more than one live hold: must always be 0. Reads the PRIMARY. */
    @Transactional
    public long doubleBookedSeats() {
        return jdbc.sql("""
                SELECT count(*) FROM (
                    SELECT hs.seat_id
                    FROM inventory.hold_seats hs
                    JOIN inventory.holds h ON h.id = hs.hold_id
                    WHERE h.status IN ('ACTIVE', 'CONFIRMED')
                    GROUP BY hs.seat_id
                    HAVING count(*) &gt; 1) AS doubles""")
                .query(Long.class)
                .single();
    }
}
</code></pre> services/inventory/src/main/java/boxoffice/inventory/InventoryController.java<pre><code>package boxoffice.inventory;

